/** @jsxImportSource react */

import { cn } from '@videojs/utils/style';
import type { ReactNode } from 'react';

import { Container as ContainerPrimitive, Slider as SliderPrimitive } from '../../skin-primitives';
import { ErrorDialog } from '../shared/skins/compat/shared/error-dialog';
import { StatusAnnouncer } from '../shared/skins/compat/shared/status-announcer';
import { PlaybackHotkeys } from '../shared/skins/shared/behaviors/playback-hotkeys';
import { AudioControls } from './controls';

export interface AudioSkinProps extends Omit<ContainerPrimitive.Props, 'children'> {
  children?: ReactNode;
  renderThumbnail?: SliderPrimitive.Thumbnail.ImageProps['render'];
}

export function AudioSkin({ children, className, renderThumbnail, ...props }: AudioSkinProps = {}) {
  return (
    <ContainerPrimitive
      className={cn('media-skin', 'media-container', 'media-audio', className)}
      data-theme="compat"
      data-preset="audio"
      {...props}
    >
      {children}
      <ErrorDialog />
      <AudioControls renderThumbnail={renderThumbnail} />

      <PlaybackHotkeys />
      <StatusAnnouncer />
    </ContainerPrimitive>
  );
}
